import React, { useState, useEffect } from 'react';
import api from '../api';

function CustomerPage() {

    const [customers, setCustomers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [showForm, setShowForm] = useState(false);
    const [editingItem, setEditingItem] = useState(null);

    const [firstName, setFirstName] = useState('');
    const [lastName, setLastName] = useState('');
    const [email, setEmail] = useState('');
    const [phone, setPhone] = useState('');
    const [licenseNumber, setLicenseNumber] = useState('');
    const [address, setAddress] = useState('');

    function fetchCustomers() {

        setLoading(true);

        api.findAllCustomers().then(function(response) {

            setCustomers(response.data);
            setError('');
            setLoading(false);

        }).catch(function() {

            setError('Failed to fetch customers.');
            setLoading(false);

        });

    }

    useEffect(function() {
        fetchCustomers();
    }, []);

    function resetForm() {

        setFirstName('');
        setLastName('');
        setEmail('');
        setPhone('');
        setLicenseNumber('');
        setAddress('');
        setEditingItem(null);

    }

    function openEditForm(customer) {

        setFirstName(customer.firstName);
        setLastName(customer.lastName);
        setEmail(customer.email || '');
        setPhone(customer.phone);
        setLicenseNumber(customer.licenseNumber);
        setAddress(customer.address || '');
        setEditingItem(customer);
        setShowForm(true);

    }

    function handleSubmit(e) {

        e.preventDefault();

        const data = {
            firstName: firstName,
            lastName: lastName,
            email: email,
            phone: phone,
            licenseNumber: licenseNumber,
            address: address
        };

        if (editingItem) {

            api.updateCustomer(editingItem.id, data).then(function() {

                resetForm();
                setShowForm(false);
                fetchCustomers();

            }).catch(function(err) {
                var message = err.response?.data?.message || 'Failed to update customer.';
                setError(message);
            });

        } else {

            api.saveCustomer(data).then(function() {

                resetForm();
                setShowForm(false);
                fetchCustomers();

            }).catch(function(err) {
                var message = err.response?.data?.message || 'Failed to save customer.';
                setError(message);
            });

        }

    }

    function handleDelete(id) {

        var confirmed = window.confirm('Delete this customer?');

        if (!confirmed) {
            return;
        }

        api.deleteCustomer(id).then(function() {
            fetchCustomers();
        }).catch(function(err) {
            var message = err.response?.data?.message || 'Failed to delete customer.';
            setError(message);
        });

    }

    if (loading) {

        return (
            <div style={{ textAlign: 'center', padding: '2rem' }}>
                <p>Loading customers...</p>
            </div>
        );

    }

    return (

        <div>

            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>

                <h2 style={{ margin: 0, color: '#1a1a2e' }}>Customers</h2>

                <button onClick={function() { resetForm(); setShowForm(true); }}
                    style={{ background: '#fbbf24', color: '#1a1a2e', border: 'none', padding: '0.5rem 1rem', borderRadius: '8px', cursor: 'pointer', fontWeight: 600 }}>
                    Add Customer
                </button>

            </div>

            {error && (

                <div style={{ background: '#fef2f2', color: '#dc2626', padding: '0.75rem 1rem', borderRadius: '8px', marginBottom: '1rem', display: 'flex', justifyContent: 'space-between' }}>

                    <span>Error: {error}</span>

                    <button onClick={function() { setError(''); }}
                        style={{ background: 'none', border: 'none', color: '#dc2626', cursor: 'pointer', fontWeight: 'bold' }}>
                        X
                    </button>

                </div>

            )}

            {showForm && (

                <div style={{ background: '#fff', borderRadius: '12px', padding: '1.5rem', marginBottom: '1.5rem', border: '1px solid #e5e7eb' }}>

                    <h3 style={{ margin: '0 0 1rem', color: '#1a1a2e' }}>
                        {editingItem ? 'Edit Customer' : 'Add New Customer'}
                    </h3>

                    <form onSubmit={handleSubmit}>

                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.8rem', marginBottom: '0.8rem' }}>

                            <div>

                                <label style={{ display: 'block', marginBottom: '0.25rem', fontWeight: 500, color: '#374151' }}>
                                    First Name
                                </label>

                                <input type="text" value={firstName}
                                    onChange={function(e) { setFirstName(e.target.value); }}
                                    required
                                    placeholder="e.g. Juma"
                                    style={{ width: '100%', padding: '0.6rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', boxSizing: 'border-box' }} />

                            </div>

                            <div>

                                <label style={{ display: 'block', marginBottom: '0.25rem', fontWeight: 500, color: '#374151' }}>
                                    Last Name
                                </label>

                                <input type="text" value={lastName}
                                    onChange={function(e) { setLastName(e.target.value); }}
                                    required
                                    placeholder="e.g. Mohamed"
                                    style={{ width: '100%', padding: '0.6rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', boxSizing: 'border-box' }} />

                            </div>

                        </div>

                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.8rem', marginBottom: '0.8rem' }}>

                            <div>

                                <label style={{ display: 'block', marginBottom: '0.25rem', fontWeight: 500, color: '#374151' }}>
                                    Email
                                </label>

                                <input type="email" value={email}
                                    onChange={function(e) { setEmail(e.target.value); }}
                                    placeholder="e.g. juma@email.com"
                                    style={{ width: '100%', padding: '0.6rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', boxSizing: 'border-box' }} />

                            </div>

                            <div>

                                <label style={{ display: 'block', marginBottom: '0.25rem', fontWeight: 500, color: '#374151' }}>
                                    Phone
                                </label>

                                <input type="text" value={phone}
                                    onChange={function(e) { setPhone(e.target.value); }}
                                    required
                                    placeholder="e.g. +255-712-345-678"
                                    style={{ width: '100%', padding: '0.6rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', boxSizing: 'border-box' }} />

                            </div>

                        </div>

                        <div style={{ marginBottom: '0.8rem' }}>

                            <label style={{ display: 'block', marginBottom: '0.25rem', fontWeight: 500, color: '#374151' }}>
                                License Number
                            </label>

                            <input type="text" value={licenseNumber}
                                onChange={function(e) { setLicenseNumber(e.target.value); }}
                                required
                                placeholder="e.g. DL-2022-001"
                                style={{ width: '100%', padding: '0.6rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', boxSizing: 'border-box' }} />

                        </div>

                        <div style={{ marginBottom: '1rem' }}>

                            <label style={{ display: 'block', marginBottom: '0.25rem', fontWeight: 500, color: '#374151' }}>
                                Address
                            </label>

                            <input type="text" value={address}
                                onChange={function(e) { setAddress(e.target.value); }}
                                placeholder="e.g. 12 Kinondoni, Dar es Salaam"
                                style={{ width: '100%', padding: '0.6rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', boxSizing: 'border-box' }} />

                        </div>

                        <div style={{ display: 'flex', gap: '0.75rem' }}>

                            <button type="submit"
                                style={{ flex: 1, padding: '0.6rem', background: '#059669', color: '#fff', border: 'none', borderRadius: '8px', fontWeight: 600, cursor: 'pointer' }}>
                                {editingItem ? 'Update' : 'Save'}
                            </button>

                            <button type="button" onClick={function() { setShowForm(false); resetForm(); }}
                                style={{ padding: '0.6rem 1.2rem', background: '#f3f4f6', color: '#374151', border: '1px solid #d1d5db', borderRadius: '8px', cursor: 'pointer' }}>
                                Cancel
                            </button>

                        </div>

                    </form>

                </div>

            )}

            {!showForm && customers.length === 0 && (

                <div style={{ textAlign: 'center', padding: '2rem', background: '#fff', borderRadius: '10px', border: '1px solid #e5e7eb' }}>

                    <p style={{ color: '#6b7280' }}>No customers added yet.</p>

                </div>

            )}

            {!showForm && customers.map(function(customer) {

                return (

                    <div key={customer.id}
                        style={{ background: '#fff', borderRadius: '10px', padding: '1rem', marginBottom: '0.75rem', border: '1px solid #e5e7eb' }}>

                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>

                            <div>

                                <div style={{ fontWeight: 600, color: '#111827' }}>
                                    {customer.firstName} {customer.lastName}
                                </div>

                                <div style={{ fontSize: '0.85rem', color: '#6b7280', marginTop: '0.2rem' }}>
                                    Phone: {customer.phone}
                                </div>

                                {customer.email && (
                                    <div style={{ fontSize: '0.85rem', color: '#6b7280' }}>
                                        Email: {customer.email}
                                    </div>
                                )}

                                <div style={{ fontSize: '0.85rem', color: '#6b7280' }}>
                                    License: {customer.licenseNumber}
                                </div>

                                {customer.address && (
                                    <div style={{ fontSize: '0.85rem', color: '#6b7280' }}>
                                        {customer.address}
                                    </div>
                                )}

                            </div>

                            <div style={{ display: 'flex', gap: '0.4rem' }}>

                                <button onClick={function() { openEditForm(customer); }}
                                    style={{ background: '#fffbeb', color: '#92400e', border: '1px solid #fde68a', padding: '0.35rem 0.7rem', borderRadius: '6px', cursor: 'pointer', fontSize: '0.8rem' }}>
                                    Edit
                                </button>

                                <button onClick={function() { handleDelete(customer.id); }}
                                    style={{ background: '#fef2f2', color: '#dc2626', border: '1px solid #fecaca', padding: '0.35rem 0.7rem', borderRadius: '6px', cursor: 'pointer', fontSize: '0.8rem' }}>
                                    Delete
                                </button>

                            </div>

                        </div>

                    </div>

                );

            })}

        </div>

    );

}

export default CustomerPage;
